/** On-demand diagnostics. These observers never alter battle decisions or RNG. */
import {counterCandidate, counterSimulation, prepareRaidCounterScenario, type RaidCounterSettings} from './raid_counters.js';
import type {CalculatorEntry} from './types.js';
import type {Simulation} from './super_mega_raid_simulator.js';

export interface CounterPick {formId: string; fastMoveId: string; chargedMoveId: string; shadow: boolean}
interface Life {
    fast: number;
    charged: number;
    fastSurvived: number;
    chargedSurvived: number;
    fainted: boolean;
    fieldSeconds: number;
    damage: number;
}
interface Outing {damage: number; completed: boolean}

/** Strict survival: damage equal to HP is a KO, not a survived hit. */
export function survivedHitLimit(hp: number, damage: number): number {
    if (![hp, damage].every(Number.isFinite) || !(hp > 0) || !(damage > 0)) throw new Error('HP and damage must be positive and finite.');
    return Math.max(0, Math.ceil(hp / damage) - 1);
}

/** First-charge burst after an immediate boss charged hit, with that move chained. */
export function hitAssistedChargeScenario(
    hp: number, bossChargedDamage: number, bossChargedSeconds: number,
    fastEnergy: number, attackerFastDamage: number, attackerFastSeconds: number,
    chargedEnergy: number, attackerChargedDamage: number, attackerChargedSeconds: number,
) {
    if (![hp, bossChargedDamage, bossChargedSeconds, chargedEnergy,
        fastEnergy, attackerFastDamage, attackerFastSeconds,
        attackerChargedDamage, attackerChargedSeconds].every(Number.isFinite)
        || hp <= 0 || bossChargedDamage <= 0 || bossChargedSeconds <= 0
        || fastEnergy <= 0 || attackerFastDamage <= 0 || attackerFastSeconds <= 0
        || chargedEnergy <= 0 || chargedEnergy > 100
        || attackerChargedDamage <= 0 || attackerChargedSeconds <= 0) {
        throw new Error('Invalid hit-assisted charge inputs.');
    }
    const energyPerHit = Math.floor(bossChargedDamage / 2);
    const survivableHits = survivedHitLimit(hp, bossChargedDamage);
    let hpRemaining = hp;
    let energy = 0;
    let bossHits = 0;
    let fastMoves = 0;
    let damage = 0;
    const takeBossHit = () => {
        bossHits += 1;
        hpRemaining -= bossChargedDamage;
        if (hpRemaining > 0) energy = Math.min(100, energy + energyPerHit);
        return hpRemaining > 0;
    };
    // The clock begins when the first charged hit lands at zero energy.
    if (!takeBossHit()) return {reachable: false, energyPerHit, energyFromBoss: 0,
        bossHits, survivableHits, fastMoves, seconds: null, damage: 0, dps: null};
    let time = 0;
    let nextBossHit = bossChargedSeconds;
    let charged = energy >= chargedEnergy;
    if (charged) energy -= chargedEnergy;
    let nextPlayerHit = charged ? attackerChargedSeconds : attackerFastSeconds;
    for (let events = 0; events < 1000; events += 1) {
        // Matching the raid engine, an already-started player action lands before
        // a boss hit at the exact same timestamp.
        if (nextPlayerHit <= nextBossHit + 1e-9) {
            time = nextPlayerHit;
            if (charged) {
                damage += attackerChargedDamage;
                return {reachable: true, energyPerHit,
                    energyFromBoss: Math.min(100, bossHits * energyPerHit),
                    bossHits, survivableHits, fastMoves, seconds: time, damage,
                    dps: damage / time};
            }
            fastMoves += 1;
            damage += attackerFastDamage;
            energy = Math.min(100, energy + fastEnergy);
            charged = energy >= chargedEnergy;
            if (charged) energy -= chargedEnergy;
            nextPlayerHit = time + (charged ? attackerChargedSeconds : attackerFastSeconds);
        } else {
            time = nextBossHit;
            if (!takeBossHit()) return {reachable: false, energyPerHit,
                energyFromBoss: Math.min(100, (bossHits - 1) * energyPerHit),
                bossHits, survivableHits, fastMoves, seconds: null, damage, dps: null};
            nextBossHit += bossChargedSeconds;
        }
    }
    throw new Error('Hit-assisted charge scenario did not converge.');
}

/** Stable convolution for K ~ Binomial(n,p); handles p=0/1 and either damage ordering. */
export function binomialSurvival(hp: number, fastDamage: number, chargedDamage: number, p: number, hits: number): number {
    if (![hp, fastDamage, chargedDamage, p].every(Number.isFinite)
        || hp <= 0 || fastDamage <= 0 || chargedDamage <= 0 || p < 0 || p > 1
        || !Number.isInteger(hits) || hits < 0 || hits > 500) throw new Error('Invalid binomial survival inputs.');
    let probabilities = [1];
    for (let n = 0; n < hits; n += 1) {
        const next = Array(n + 2).fill(0);
        for (let k = 0; k <= n; k += 1) {
            next[k] += probabilities[k] * (1 - p);
            next[k + 1] += probabilities[k] * p;
        }
        probabilities = next;
    }
    return Math.min(1, Math.max(0, probabilities.reduce((sum, probability, k) =>
        sum + ((hits - k) * fastDamage + k * chargedDamage < hp ? probability : 0), 0)));
}

export function observeCounterTrial(simulation: Simulation) {
    const player = simulation.players[0];
    const lives: Life[] = [];
    let currentLives = new Map<number, Life>();
    const outings: Outing[] = [];
    let outing: Outing | null = {damage: 0, completed: false};
    let bossFastHits = 0;
    let bossChargedHits = 0;
    let activeLife: Life | null = null;
    let activeSince = simulation.current_time;
    const touch = (index: number) => {
        let life = currentLives.get(index);
        if (!life) {
            life = {fast: 0, charged: 0, fastSurvived: 0, chargedSurvived: 0,
                fainted: false, fieldSeconds: 0, damage: 0};
            currentLives.set(index, life);
            lives.push(life);
        }
        return life;
    };
    const settleActiveTime = (time: number) => {
        if (activeLife) activeLife.fieldSeconds += Math.max(0, time - activeSince);
    };
    simulation.capture_replay_state = () => {
        const nextLife = player.on_field ? touch(player.pokemon_index) : null;
        if (nextLife !== activeLife) {
            settleActiveTime(simulation.current_time);
            activeLife = nextLife;
            activeSince = simulation.current_time;
        }
        if (!player.on_field && outing) {
            outing.completed = true;
            outings.push(outing);
            outing = null;
        }
    };
    const playerHit = simulation.apply_player_hit.bind(simulation);
    simulation.apply_player_hit = (id, generation, move) => {
        const life = player.on_field ? touch(player.pokemon_index) : null;
        const fastBefore = player.fast_moves_used;
        const chargedBefore = player.charged_moves_used;
        const hpBefore = Math.max(0, simulation.boss_hp);
        playerHit(id, generation, move);
        if (life) {
            life.fast += player.fast_moves_used - fastBefore;
            life.charged += player.charged_moves_used - chargedBefore;
            const damage = hpBefore - Math.max(0, simulation.boss_hp);
            if (damage > 0) {
                life.damage += damage;
            }
        }
        if (outing) outing.damage += hpBefore - Math.max(0, simulation.boss_hp);
    };
    const bossHit = simulation.apply_boss_hit.bind(simulation);
    simulation.apply_boss_hit = (move, dodgers) => {
        const pokemon = player.pokemon;
        const life = player.on_field ? touch(player.pokemon_index) : null;
        const charged = move === simulation.boss_charged;
        // Fit the marginal probability to attacks that actually reach the team.
        if (life) { if (charged) bossChargedHits++; else bossFastHits++; }
        bossHit(move, dodgers);
        if (life) {
            if (pokemon.hp <= 0) life.fainted = true;
            else if (charged) life.chargedSurvived++;
            else life.fastSurvived++;
        }
    };
    const rejoin = simulation.rejoin.bind(simulation);
    simulation.rejoin = (time, id) => {
        currentLives = new Map();
        outing = {damage: 0, completed: false};
        rejoin(time, id);
    };
    return {
        finish(finalTime = simulation.current_time) {
            settleActiveTime(finalTime);
            activeLife = null;
            if (outing) outings.push(outing);
            return {lives, outings, bossFastHits, bossChargedHits};
        },
    };
}

const mean = (values: number[]) => values.length ? values.reduce((sum, value) => sum + value, 0) / values.length : null;
const averageNullable = (values: (number | null)[]) => values.every(value => value !== null)
    ? mean(values as number[]) : null;

export function calculateCounterBreakdown(
    catalog: CalculatorEntry[], settings: RaidCounterSettings, pick: CounterPick,
    shadows: ReadonlySet<string> = new Set(), legendaries: ReadonlySet<number> = new Set(),
    trialsPerMoveset = 32,
) {
    if (!Number.isInteger(trialsPerMoveset) || trialsPerMoveset < 1 || trialsPerMoveset > 128) {
        throw new Error('Detail trials must be an integer from 1 through 128.');
    }
    const {engine, bossMovePairs, allBossMovePairs, level, megaLevel} = prepareRaidCounterScenario(catalog, settings);
    const candidate = counterCandidate(catalog, pick, settings, shadows, legendaries);
    const movesets = bossMovePairs.map(pair => {
        const lives: Life[] = [];
        const outings: Outing[] = [];
        const firstOutingDamage: number[] = [];
        let fastHits = 0;
        let chargedHits = 0;
        let totalSeconds = 0;
        let totalDamage = 0;
        for (let trial = 0; trial < trialsPerMoveset; trial++) {
            const simulation = counterSimulation(engine, candidate, pair, level, megaLevel, trial);
            const observer = observeCounterTrial(simulation);
            const result = simulation.run();
            const observation = observer.finish(result.finish_time);
            lives.push(...observation.lives);
            outings.push(...observation.outings);
            firstOutingDamage.push(observation.outings[0].damage);
            fastHits += observation.bossFastHits;
            chargedHits += observation.bossChargedHits;
            totalDamage += engine.BOSS_HP - result.boss_hp;
            totalSeconds += result.finish_time;
        }
        const fainted = lives.filter(life => life.fainted);
        const dpsLives = fainted.length ? fainted : lives;
        const usableDpsLives = dpsLives.filter(life => life.fieldSeconds > 0 && life.damage > 0);
        const completed = outings.filter(outing => outing.completed);
        const partial = outings.filter(outing => !outing.completed);
        const observedChargedProbability = fastHits + chargedHits ? chargedHits / (fastHits + chargedHits) : null;
        const sample = counterSimulation(engine, candidate, pair, level, megaLevel, 0);
        const pokemon = sample.players[0].pokemon;
        const hp = pokemon.max_hp;
        // Hidden Power is fixed within a raid, uniformly random across raids.
        // Average probabilities for each possible type, never average damage first.
        const fastTypes = pair.engineFast.name === 'Hidden Power' ? engine.HIDDEN_POWER_TYPES : [pair.engineFast.move_type];
        const phases = (engine.SHADOW_RAID || engine.SUPER_MEGA_ENRAGE) ? [false, true] : [false];
        const survival = phases.map(enraged => {
            const fastDamages = fastTypes.map((type: string) => {
                const move = Object.assign(Object.create(Object.getPrototypeOf(pair.engineFast)), pair.engineFast, {move_type: type});
                return engine.incoming_damage_for_pokemon(move, pokemon, enraged, false, 1);
            });
            const chargedDamage = engine.incoming_damage_for_pokemon(pair.engineCharged, pokemon, enraged, false, 1);
            const dodgedChargedDamage = engine.incoming_damage_for_pokemon(pair.engineCharged, pokemon, enraged, true, 1);
            sample.enraged = enraged;
            const attackerFastDamage = sample.outgoing_damage(pokemon.fast_move, 0, false);
            const attackerChargedDamage = sample.outgoing_damage(pokemon.charged_move, 0, false);
            const hitAssistedCharge = hitAssistedChargeScenario(hp, chargedDamage, pair.engineCharged.duration,
                pokemon.fast_move.energy, attackerFastDamage, pokemon.fast_move.duration,
                pokemon.charged_move.energy, attackerChargedDamage, pokemon.charged_move.duration);
            const combos = Array.from({length: Math.min(12, survivedHitLimit(hp, chargedDamage) + 1) + 1}, (_, charges) => {
                const hpRemaining = hp - charges * chargedDamage;
                return {chargedHits: charges, survives: hpRemaining > 0,
                    fastHitsMin: hpRemaining > 0 ? Math.min(...fastDamages.map(d => survivedHitLimit(hpRemaining, d))) : 0,
                    fastHitsMax: hpRemaining > 0 ? Math.max(...fastDamages.map(d => survivedHitLimit(hpRemaining, d))) : 0};
            });
            const limit = Math.min(60, survivedHitLimit(hp, Math.min(chargedDamage, ...fastDamages)) + 1);
            const curve = Array.from({length: limit + 1}, (_, hits) => ({hits,
                survivalProbability: observedChargedProbability === null ? null : mean(fastDamages.map(d =>
                    binomialSurvival(hp, d, chargedDamage, observedChargedProbability, hits))),
            }));
            return {phase: enraged ? 'Enraged' : 'Normal', hp,
                fastDamageMin: Math.min(...fastDamages), fastDamageMax: Math.max(...fastDamages),
                chargedDamage, dodgedChargedDamage,
                hitAssistedCharge,
                chargedHitsSurvived: survivedHitLimit(hp, chargedDamage), combos, curve,
                curveTruncated: limit === 60 && survivedHitLimit(hp, Math.min(chargedDamage, ...fastDamages)) >= 60};
        });
        // 12+ tail keeps a bulky counter's distribution compact without losing probability mass.
        const cycleDistribution = Array.from({length: 13}, (_, cycles) => ({cycles,
            probability: fainted.length ? fainted.filter(life => Math.min(12, life.charged) === cycles).length / fainted.length : null}));
        return {fastMoveId: pair.fastMove.id, chargedMoveId: pair.chargedMove.id,
            fastMove: pair.fastMove.name, chargedMove: pair.chargedMove.name,
            trials: trialsPerMoveset, hp, completedLives: fainted.length, unfinishedLives: lives.length - fainted.length,
            chargedCyclesPerLife: mean(fainted.map(life => life.charged)),
            fastMovesPerLife: mean(fainted.map(life => life.fast)),
            fieldSecondsPerLife: mean(fainted.map(life => life.fieldSeconds)),
            averageOnFieldDps: usableDpsLives.length
                ? usableDpsLives.reduce((sum, life) => sum + life.damage, 0)
                    / usableDpsLives.reduce((sum, life) => sum + life.fieldSeconds, 0)
                : null,
            hitAssistedDps: survival[0].hitAssistedCharge.dps,
            bossFastHitsSurvived: mean(fainted.map(life => life.fastSurvived)),
            bossChargedHitsSurvived: mean(fainted.map(life => life.chargedSurvived)),
            completedOutings: completed.length, partialOutings: partial.length,
            damagePerCompletedOuting: mean(completed.map(outing => outing.damage)),
            damagePerPartialOuting: mean(partial.map(outing => outing.damage)),
            firstOutingDamage: mean(firstOutingDamage)!,
            battleDps: totalDamage / Math.max(1e-9, totalSeconds),
            observedChargedProbability, cycleDistribution, survival,
        };
    }).sort((a, b) => a.battleDps - b.battleDps
        || a.fastMove.localeCompare(b.fastMove) || a.chargedMove.localeCompare(b.chargedMove));
    const reachableHitAssisted = movesets.map(pair => pair.hitAssistedDps)
        .filter((value): value is number => value !== null);
    return {
        pick, attackerFastMove: candidate.fastMove.name, attackerChargedMove: candidate.chargedMove.name,
        bossHp: engine.BOSS_HP, trialsPerMoveset, simulatedBattles: movesets.length * trialsPerMoveset,
        totalBossMovesets: allBossMovePairs.length, movesets,
        // Equal weighting across tested movesets; null if any pair is entirely censored.
        average: {
            chargedCyclesPerLife: averageNullable(movesets.map(pair => pair.chargedCyclesPerLife)),
            fastMovesPerLife: averageNullable(movesets.map(pair => pair.fastMovesPerLife)),
            fieldSecondsPerLife: averageNullable(movesets.map(pair => pair.fieldSecondsPerLife)),
            averageOnFieldDps: averageNullable(movesets.map(pair => pair.averageOnFieldDps)),
            hitAssistedDps: mean(reachableHitAssisted),
            hitAssistedReachableMovesets: reachableHitAssisted.length,
            bossFastHitsSurvived: averageNullable(movesets.map(pair => pair.bossFastHitsSurvived)),
            bossChargedHitsSurvived: averageNullable(movesets.map(pair => pair.bossChargedHitsSurvived)),
            damagePerCompletedOuting: averageNullable(movesets.map(pair => pair.damagePerCompletedOuting)),
            firstOutingDamage: mean(movesets.map(pair => pair.firstOutingDamage))!,
            cycleDistribution: Array.from({length: 13}, (_, cycles) => ({cycles,
                probability: averageNullable(movesets.map(pair => pair.cycleDistribution[cycles].probability))})),
            survival: movesets[0].survival.map((phase, phaseIndex) => ({phase: phase.phase,
                curve: Array.from({length: Math.max(...movesets.map(pair => pair.survival[phaseIndex].curve.length))}, (_, hits) => ({hits,
                    survivalProbability: averageNullable(movesets.map(pair => {
                        const curve = pair.survival[phaseIndex].curve;
                        return hits < curve.length ? curve[hits].survivalProbability : 0;
                    })),
                })),
            })),
        },
    };
}
